// newTestService builds a Service over a fresh temp store and a fresh blob
// dir; both die with the test.
func newTestService(t *testing.T) (*Service, *store.Store, string) {
	t.Helper()
	st, err := store.Open(context.Background(), filepath.Join(t.TempDir(), "test.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	root := t.TempDir()
	return NewService(st, root), st, root
}

// newUpstream spins an httptest upstream that counts every hit; serve
// renders each response (delay, status, body).
func newUpstream(t *testing.T, serve func(w http.ResponseWriter, r *http.Request)) (*httptest.Server, *atomic.Int32) {
	t.Helper()
	var hits atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits.Add(1)
		serve(w, r)
	}))
	t.Cleanup(srv.Close)
	return srv, &hits
}

// serveBytes is the fixed-response serve func: optional delay, then status
// and body.
func serveBytes(status int, body []byte, delay time.Duration) func(w http.ResponseWriter, r *http.Request) {
	return func(w http.ResponseWriter, r *http.Request) {
		if delay > 0 {
			time.Sleep(delay)
		}
		w.WriteHeader(status)
		_, _ = w.Write(body)
	}
}

// jpegBytes encodes a plain w×h RGBA frame as JPEG — a synthetic upstream
// poster.
func jpegBytes(t *testing.T, w, h int) []byte {
	t.Helper()
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			img.Set(x, y, color.RGBA{R: uint8(x), G: uint8(y), B: 128, A: 255})
		}
	}
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, img, nil); err != nil {
		t.Fatalf("encode %dx%d jpeg: %v", w, h, err)
	}
	return buf.Bytes()
}

// pngBytes is the PNG twin of jpegBytes — same frame, different container,
// so the two never share a content address.
func pngBytes(t *testing.T, w, h int) []byte {
	t.Helper()
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		t.Fatalf("encode %dx%d png: %v", w, h, err)
	}
	return buf.Bytes()
}

// TestServiceAcquire covers the fetch-once contract: sequential dedup (one
// upstream hit for repeated (url, kind)), the singleflight collapse of
// concurrent producers, kind-keyed partitioning, the disk-miss self-heal,
// the failure cooldown skip, and the guard rejections (ErrNotImage /
// ErrTooLarge).
func TestServiceAcquire(t *testing.T) {
	ctx := context.Background()
	svc, st, root := newTestService(t)

	poster := jpegBytes(t, 400, 300)
	srv, hits := newUpstream(t, serveBytes(http.StatusOK, poster, 0))
	url := srv.URL + "/poster.jpg"

	t.Run("fetch_once_and_dedup", func(t *testing.T) {
		sha1, err := svc.Acquire(ctx, url, "") // empty kind → KindPoster
		if err != nil {
			t.Fatalf("Acquire #1: %v", err)
		}
		if sha1 != sha256Hex(poster) {
			t.Fatalf("sha = %s, want the content address %s", sha1, sha256Hex(poster))
		}
		// Same (url, kind) again — this time with the explicit kind — must
		// ride the fetch row, never the wire.
		sha2, err := svc.Acquire(ctx, url, KindPoster)
		if err != nil {
			t.Fatalf("Acquire #2: %v", err)
		}
		if sha2 != sha1 {
			t.Fatalf("sha #2 = %s, want stable %s", sha2, sha1)
		}
		if got := hits.Load(); got != 1 {
			t.Fatalf("upstream hits = %d, want 1 (fetch-once)", got)
		}
		if row, err := st.LookupArtFetch(ctx, urlHash(url, KindPoster)); err != nil || row != sha1 {
			t.Fatalf("LookupArtFetch = %q, %v; want %q", row, err, sha1)
		}
		if _, err := os.Stat(filepath.Join(root, sha1, "original.jpeg")); err != nil {
			t.Fatalf("original blob missing: %v", err)
		}
	})

	// singleflight_collapse: N concurrent producers of the SAME (url, kind)
	// collapse into ONE upstream fetch; every caller gets the same sha.
	t.Run("singleflight_collapse", func(t *testing.T) {
		slow := jpegBytes(t, 40, 60)
		srv2, hits2 := newUpstream(t, serveBytes(http.StatusOK, slow, 200*time.Millisecond))
		u2 := srv2.URL + "/sf.jpg"
		const n = 8
		start := make(chan struct{})
		var (
			wg   sync.WaitGroup
			shas = make([]string, n)
			errs = make([]error, n)
		)
		for i := 0; i < n; i++ {
			wg.Add(1)
			go func(i int) {
				defer wg.Done()
				<-start
				shas[i], errs[i] = svc.Acquire(ctx, u2, "poster")
			}(i)
		}
		close(start)
		wg.Wait()
		for i := 0; i < n; i++ {
			if errs[i] != nil {
				t.Fatalf("Acquire #%d: %v", i, errs[i])
			}
			if shas[i] != sha256Hex(slow) {
				t.Fatalf("sha #%d = %s, want %s", i, shas[i], sha256Hex(slow))
			}
		}
		if got := hits2.Load(); got != 1 {
			t.Fatalf("upstream hits = %d, want 1 (singleflight collapse)", got)
		}
	})

	// kind_partitions: the same url under two kinds is two cache keys — two
	// fetches (the derived crops differ), never a shared row.
	t.Run("kind_partitions", func(t *testing.T) {
		srv3, hits3 := newUpstream(t, serveBytes(http.StatusOK, poster, 0))
		u3 := srv3.URL + "/both.jpg"
		if _, err := svc.Acquire(ctx, u3, "poster"); err != nil {
			t.Fatalf("Acquire poster: %v", err)
		}
		if _, err := svc.Acquire(ctx, u3, "background"); err != nil {
			t.Fatalf("Acquire background: %v", err)
		}
		if got := hits3.Load(); got != 2 {
			t.Fatalf("upstream hits = %d, want 2 (kinds never share a key)", got)
		}
	})

	// disk_miss_refetches: a fetch row whose blob vanished (fresh Service,
	// empty dir) re-fetches and re-points the row — the self-heal that keeps
	// a replaced upload recoverable.
	t.Run("disk_miss_refetches", func(t *testing.T) {
		body := jpegBytes(t, 30, 45)
		srv4, hits4 := newUpstream(t, serveBytes(http.StatusOK, body, 0))
		u4 := srv4.URL + "/heal.jpg"
		sha1, err := svc.Acquire(ctx, u4, "poster")
		if err != nil {
			t.Fatalf("Acquire #1: %v", err)
		}
		svc2 := NewService(st, t.TempDir()) // same store, empty blob dir
		sha2, err := svc2.Acquire(ctx, u4, "poster")
		if err != nil {
			t.Fatalf("Acquire #2 (empty dir): %v", err)
		}
		if sha2 != sha1 {
			t.Fatalf("sha = %s, want stable %s", sha2, sha1)
		}
		if got := hits4.Load(); got != 2 {
			t.Fatalf("upstream hits = %d, want 2 (missing blob re-fetched)", got)
		}
	})

	// cooldown_skips_upstream: after a failure, the hash is skipped for
	// ~10 min — the retry must not touch the wire (hits stay at 1).
	t.Run("cooldown_skips_upstream", func(t *testing.T) {
		srv5, hits5 := newUpstream(t, serveBytes(http.StatusInternalServerError, []byte("nope"), 0))
		u5 := srv5.URL + "/down.jpg"
		if _, err := svc.Acquire(ctx, u5, "poster"); err == nil {
			t.Fatal("Acquire on a 500 upstream = nil error, want failure")
		}
		if _, err := svc.Acquire(ctx, u5, "poster"); err == nil {
			t.Fatal("cooled Acquire = nil error, want cooldown refusal")
		}
		if got := hits5.Load(); got != 1 {
			t.Fatalf("upstream hits = %d, want 1 (cooldown skipped the retry)", got)
		}
	})

	// guard_rejections: non-image bytes, oversized bytes, and a corrupt
	// image that sniffs fine — all refused by the one guard, none stored.
	t.Run("guard_rejections", func(t *testing.T) {
		oversize := bytes.Repeat([]byte{0xFF, 0xD8, 0xFF}, 3<<20) // 9 MiB of JPEG magic
		corrupt := append([]byte{0xFF, 0xD8, 0xFF, 0xE0}, bytes.Repeat([]byte{0x00}, 1024)...)
		cases := []struct {
			name string
			body []byte
			want error
		}{
			{"not_image", []byte("hello world, definitely not an image"), ErrNotImage},
			{"too_large", oversize, ErrTooLarge},
			{"corrupt_sniffing_jpeg", corrupt, ErrNotImage},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				srvC, _ := newUpstream(t, serveBytes(http.StatusOK, tc.body, 0))
				if _, err := svc.Acquire(ctx, srvC.URL, "poster"); !errors.Is(err, tc.want) {
					t.Fatalf("Acquire = %v, want errors.Is %v", err, tc.want)
				}
			})
		}
	})
}
